<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue';import axios from 'axios';import {useRoute,useRouter,RouterLink} from 'vue-router';
const route=useRoute(),router=useRouter(),person=ref<any>(null),error=ref(''),sell=ref<any[]>([]),wanted=ref<any[]>([]),moreSell=ref(false),moreWanted=ref(false),loadingSell=ref(false),loadingWanted=ref(false),contacting=ref(false);let sequence=0;
async function load(kind:string,append=false){const current=sequence,id=String(route.params.id),list=kind==='SELL'?sell:wanted,busy=kind==='SELL'?loadingSell:loadingWanted;if(busy.value)return;busy.value=true;try{const {data}=await axios.get('/api/people/'+id+'/listings',{params:{kind,before:append?list.value.at(-1)?.id:0}});if(current!==sequence)return;const ids=new Set(list.value.map(p=>p.id));list.value=append?[...list.value,...data.filter((p:any)=>!ids.has(p.id))]:data;(kind==='SELL'?moreSell:moreWanted).value=data.length===12;}catch{if(current===sequence)error.value='发布信息加载失败，请重试';}finally{if(current===sequence)busy.value=false;}}
async function contact(){if(contacting.value||!person.value)return;contacting.value=true;const current=sequence,peer=person.value.id;try{const token=(await axios.get('/api/auth/csrf')).data.token;const {data}=await axios.post('/api/chats/with/'+peer,null,{headers:{'X-XSRF-TOKEN':token}});if(current===sequence)router.push('/messages/'+data.id);}catch{if(current===sequence)error.value='暂时无法发起私聊';}finally{if(current===sequence)contacting.value=false;}}
watch(()=>route.params.id,async()=>{const current=++sequence,id=String(route.params.id);error.value='';person.value=null;sell.value=[];wanted.value=[];moreSell.value=moreWanted.value=false;loadingSell.value=loadingWanted.value=false;contacting.value=false;try{const me=(await axios.get('/api/people/me')).data;if(current!==sequence)return;if(String(me.id)===id){router.replace('/my/products');return;}const {data}=await axios.get('/api/people/'+id);if(current!==sequence)return;person.value=data;await Promise.all([load('SELL'),load('WANTED')]);}catch{if(current===sequence)error.value='用户不存在或加载失败';}},{immediate:true});
onUnmounted(()=>sequence++);
</script><template><section class="public-profile"><p>SDU / CAMPUS PROFILE</p><p role="alert">{{error}}</p><template v-if="person"><header><img :src="'/api/conversations/avatars/'+person.id" alt="用户头像"><div><h1>{{person.username}}</h1><small>ID {{person.id}}</small><p>{{person.signature||'还没有填写个性签名'}}</p></div><button :disabled="contacting" @click="contact">{{contacting?'打开私聊…':'联系TA'}}</button></header><div class="info"><span>QQ：{{person.qq||'未填写'}}</span><span>宿舍楼：{{person.dormitory||'未填写'}}</span><span>校园地点：{{person.location||'未填写'}}</span></div><section v-for="kind in ['SELL','WANTED']" :key="kind"><h2>{{kind==='SELL'?'TA出售的商品':'TA感兴趣 / 求购的商品'}}</h2><div class="profile-grid"><RouterLink v-for="p in kind==='SELL'?sell:wanted" :key="p.id" :to="'/market/'+p.id"><img :src="p.imageUrl" :alt="p.title"><strong>{{p.title}}</strong><span>¥ {{Number(p.price).toFixed(2)}}</span></RouterLink></div><p v-if="!(kind==='SELL'?sell:wanted).length">暂无发布。</p><button :disabled="kind==='SELL'?loadingSell:loadingWanted" v-if="kind==='SELL'?moreSell:moreWanted" @click="load(kind,true)">加载更多</button></section></template></section></template><style scoped>.public-profile{flex:1;background:#f6f4ee;color:#293d3b;padding:35px 6%}.public-profile>p:first-child{font-size:10px;letter-spacing:2px;color:#96764e}header{display:flex;gap:25px;align-items:center;flex-wrap:wrap;padding:25px;background:#fffaf2;border-radius:12px}header>img{width:85px;height:85px;border-radius:50%;object-fit:cover}h1{font-size:30px;margin:10px 0}small{font-size:11px;color:#8d8f7b}header p{font-size:13px}.info{display:flex;gap:25px;flex-wrap:wrap;font-size:12px;padding:22px;background:white;margin:20px 0}.profile-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.profile-grid a{background:white;padding:20px;text-decoration:none;color:#304b49;border-radius:9px}.profile-grid img{width:100%;height:150px;object-fit:contain}.profile-grid strong,.profile-grid span{display:block;margin-top:12px;overflow-wrap:anywhere}.profile-grid span{color:#a25438}button{background:#304b49;color:white;border:0;border-radius:5px;padding:12px 20px;cursor:pointer}section>h2{font-size:22px;margin:35px 0 20px}@media(max-width:600px){.profile-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
